namespace datagraph.data.graph.panel.model.column;





using docking.widgets.trable;
using docking.widgets.trable;
using resources;

/**
 * Renderer for the pointer icon column where the use can click to add vertices to the graph.
 */
public class PointerColumnRenderer : DefaultGTrableCellRenderer<Boolean> {

	private static readonly Icon ICON = Icons.RIGHT_ICON;

	/* @Override */
	public Component getCellRenderer(GTrable<object> trable, Boolean value, bool isSelected,
			bool hasFocus, int row, int column) {

		base.getCellRenderer(trable, null, isSelected, hasFocus, row, column);

		bool isPointer = value;
		Icon icon = isPointer ? ICON : null;
		setIcon(icon);
		return this;
	}
}
